const { addonBuilder, serveHTTP } = require("stremio-addon-sdk");
const axios = require("axios");

const BASE_URL = "https://cee.buzz";
const API_URL = `${BASE_URL}/api/android`;

const manifest = {
    id: "org.cee.cinemana",
        version: "1.0.0",
            name: "Cee (Cinemana)",
                description: "مشاهدة الأفلام والمسلسلات من سينمانا مباشرة",
                    resources: ["catalog", "stream", "meta"],
                        types: ["movie", "series"],
                            catalogs: [
                                    {
                                                type: "movie",
                                                            id: "cee_movies",
                                                                        name: "أفلام Cee",
                                                                                    extra: [{ name: "search", isRequired: false }]
                                                                                            },
                                                                                                    {
                                                                                                                type: "series",
                                                                                                                            id: "cee_series",
                                                                                                                                        name: "مسلسلات Cee",
                                                                                                                                                    extra: [{ name: "search", isRequired: false }]
                                                                                                                                                            }
                                                                                                                                                                ]
                                                                                                                                                                };

                                                                                                                                                                const builder = new addonBuilder(manifest);

                                                                                                                                                                builder.defineCatalogHandler(async ({ type, id, extra }) => {
                                                                                                                                                                    try {
                                                                                                                                                                            let items = [];
                                                                                                                                                                                    if (extra && extra.search) {
                                                                                                                                                                                                const query = encodeURIComponent(extra.search);
                                                                                                                                                                                                            const searchType = type === "movie" ? "movies" : "series";
                                                                                                                                                                                                                        const currentYear = new Date().getFullYear();
                                                                                                                                                                                                                                    const searchUrl = `${API_URL}/AdvancedSearch?level=0&videoTitle=${query}&staffTitle=${query}&year=1900,${currentYear}&page=0&type=${searchType}&itemsPerPage=25`;
                                                                                                                                                                                                                                                const res = await axios.get(searchUrl);
                                                                                                                                                                                                                                                            items = res.data || [];
                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                const videoKind = type === "movie" ? 1 : 2;
                                                                                                                                                                                                                                                                                            const listUrl = `${API_URL}/video/V/2?videoKind=${videoKind}&langNb=&itemsPerPage=25&pageNumber=0&level=0&sortParam=desc`;
                                                                                                                                                                                                                                                                                                        const res = await axios.get(listUrl);
                                                                                                                                                                                                                                                                                                                    items = res.data || [];
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                    const metas = items.map(item => ({
                                                                                                                                                                                                                                                                                                                                                id: `cee:${item.nb}`,
                                                                                                                                                                                                                                                                                                                                                            type: type,
                                                                                                                                                                                                                                                                                                                                                                        name: item.en_title || "بدون عنوان",
                                                                                                                                                                                                                                                                                                                                                                                    poster: item.imgObjUrl || item.img,
                                                                                                                                                                                                                                                                                                                                                                                                description: item.ar_content || ""
                                                                                                                                                                                                                                                                                                                                                                                                        }));

                                                                                                                                                                                                                                                                                                                                                                                                                return { metas };
                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                            return { metas: [] };
                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                builder.defineMetaHandler(async ({ type, id }) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                    const extractedId = id.replace("cee:", "");
                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                const detailsRes = await axios.get(`${API_URL}/allVideoInfo/id/${extractedId}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                        const details = detailsRes.data;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                const meta = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            id: `cee:${extractedId}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        type: type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    name: details.en_title || "بدون عنوان",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                poster: details.imgObjUrl || details.img,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            background: details.imgObjUrl || details.img,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        description: details.ar_content || details.en_content || "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    year: details.year,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                genres: details.categories ? details.categories.map(c => c.ar_title || c.en_title) : []
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (type === "series") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const seasonsRes = await axios.get(`${BASE_URL}/api/android/videoSeason/id/${extractedId}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const eps = seasonsRes.data || [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    meta.videos = eps.map(ep => ({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    id: `cee:${extractedId}:${ep.season || 1}:${ep.episodeNummer || 1}:${ep.nb}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    title: `الموسم ${ep.season || 1} - الحلقة ${ep.episodeNummer || 1}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    season: parseInt(ep.season || 1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    episode: parseInt(ep.episodeNummer || 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return { meta };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return { meta: null };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                builder.defineStreamHandler(async ({ type, id }) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let videoId = id.replace("cee:", "");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (type === "series") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const parts = id.split(":");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        videoId = parts[parts.length - 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const streams = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const subs = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const detailsRes = await axios.get(`${API_URL}/allVideoInfo/id/${videoId}`).catch(() => null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (detailsRes && detailsRes.data && detailsRes.data.translations) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            detailsRes.data.translations.forEach(s => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (s.file) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                subs.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        lang: s.name || "العربية",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                url: s.file
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const videosUrl = `${API_URL}/transcoddedFiles/id/${videoId}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const res = await axios.get(videosUrl, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    headers: { "Referer": BASE_URL }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const videoLinks = res.data || [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            videoLinks.reverse().forEach(v => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (v.videoUrl) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        streams.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            title: `Cee - ${v.resolution || 'الجودة التلقائية'}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                url: v.videoUrl,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    subtitles: subs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        behaviorHints: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                notWebReady: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        proxyHeaders: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    request: { "Referer": BASE_URL }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return { streams };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return { streams: [] };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const port = process.env.PORT || 7000;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            serveHTTP(builder.getInterface(), { port });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            